-- Subscriber's Portal entry (DRAFT) announcing the arcade makeover of eight games, with a moving preview of each.
-- Saved as a draft: nothing is emailed. Publishing it in the admin opens its email as a draft to review and send by hand.
-- The pictures are in assets/newsletter/arcade-update/. Run once in the Supabase SQL Editor (safe to run again).
insert into portal_entries (id, data) values ('portal-arcade-update', $j${"id": "portal-arcade-update", "slug": "arcade-makeover", "title": "Eight Games, One Big Arcade Makeover", "description": "Every game on the Play page got a new arcade look. Watch a short preview of each one and see what changed.", "category": "New games", "layout": "article", "status": "draft", "publishedAt": "2026-10-30", "cover": {"src": "assets/newsletter/arcade-update/reel.gif", "alt": "A moving preview of eight games: Spelling Detective, Cosmic Blast!, Bounce and Bank, Air Hockey Arcade, Balloon Pop Math, Maze Quest, Fruit Drop and Memory Match"}, "coverStill": "assets/newsletter/arcade-update/reel-still.jpg", "body": "<p>This week every game on our Play page got a makeover: a brand-new arcade look, sound effects you can turn off with one button, and new ways to play. Below is a short moving preview of each game and what changed.</p><h2>Spelling Detective</h2><p><img src=\"assets/newsletter/arcade-update/spelling-detective.gif\" alt=\"Spelling Detective: Chike gives a thumbs up beside a case card with the clue The green part of a tree, a wrong letter is crossed out and the word LEAF is solved\"></p><ul><li>A detective case with Chike. Read the clue on the case card and crack the hidden word.</li><li>Pick your grade, from Kindergarten to 5th. Each grade has its own words.</li><li>A wrong letter uses up one of your magnifying glasses, so think before you guess.</li><li>Stuck? Press Get a clue and Chike finds a letter for you, once per case.</li></ul><p><a href=\"#/play/game-spelling\">Play Spelling Detective</a></p><h2>Cosmic Blast!</h2><p><img src=\"assets/games/ufo-target-practice.jpg\" alt=\"Cosmic Blast!: a white spaceship flies toward Saturn, aiming at a group of flying saucers\"></p><ul><li>Fly past all eight planets, Mercury to Neptune. Each planet is a level with its own points goal.</li><li>From Earth on, some aliens shoot back. From Jupiter on, radar drones can jam your laser.</li><li>Reach the goal and a spinning black hole pulls you through to the next planet, with a fun fact about it.</li><li>Switch between three lasers. The planets you reach and your best scores are saved.</li></ul><p><a href=\"#/play/game-ufo\">Play Cosmic Blast!</a></p><h2>Bounce &amp; Bank</h2><p><img src=\"assets/newsletter/arcade-update/bounce-and-bank.gif\" alt=\"Bounce and Bank: glowing balls bounce down a neon peg board into money slots, and one lands in the $100 jackpot\"></p><ul><li>A neon arcade cabinet, with a cash receipt that prints every ball&#x27;s win.</li><li>Drop balls through glowing pegs into the slots, from the $100 jackpot to a few that cost you $10.</li><li>Spend bank money on extra balls, including 2x and 3x balls that multiply their slot.</li><li>Grow your bank to $1,000 over six games. Your all-time high score is saved.</li></ul><p><a href=\"#/play/game-bounce-and-bank\">Play Bounce &amp; Bank</a></p><h2>Air Hockey Arcade</h2><p><img src=\"assets/newsletter/arcade-update/air-hockey.gif\" alt=\"Air Hockey Arcade: a glowing 3D air hockey table in a neon arcade room, where a puck goes into Chike&#x27;s goal and the scoreboard flashes GOAL! plus 6\"></p><ul><li>Rebuilt as a full-screen 3D table. You stand at your end and Chike guards the far goal.</li><li>Five numbered pucks are in play at once. Knock one into Chike&#x27;s goal to score its number.</li><li>The LED scoreboard adds up the goals as you go. First to 25 wins.</li><li>At the end you see the whole match: every puck each side scored, added up to the final score.</li></ul><p><a href=\"#/play/game-air-hockey\">Play Air Hockey Arcade</a></p><h2>Balloon Pop Math</h2><p><img src=\"assets/newsletter/arcade-update/balloon-pop-math.gif\" alt=\"Balloon Pop Math: striped hot-air balloons with numbers float in a blue sky under the question 25 plus 27, the balloon with 52 pops and Chike says Nice\"></p><ul><li>Rebuilt with grades from Kindergarten to 5th. Each grade has its own kind of math.</li><li>Pop the balloon with the right answer, or type it. Rounds are 25 questions, with up to three stars.</li><li>After two misses Chike gives a hint, and Show me how opens his chalkboard to work it out step by step.</li><li>Your place is saved, so you can stop and come back later.</li></ul><p><a href=\"#/play/game-balloon-math\">Play Balloon Pop Math</a></p><h2>Maze Quest</h2><p><img src=\"assets/newsletter/arcade-update/maze-quest.gif\" alt=\"Maze Quest: an explorer walks through a hedge maze in Sunny Woods, then the Old Wizard appears with a math question and four answers\"></p><ul><li>Now a walk through eight forests, from the camp tent to the cabin.</li><li>Pick your explorer from 8 characters, and pick your grade from Kindergarten to 5th.</li><li>Glowing lanterns call the Old Wizard, who asks a question for your grade. Answer right and you jump ten squares ahead.</li><li>New: race a friend online. Make a room, share the 6-character code, and the first to reach the cabin wins each forest.</li></ul><p><a href=\"#/play/game-maze\">Play Maze Quest</a></p><h2>Fruit Drop</h2><p><img src=\"assets/newsletter/arcade-update/fruit-drop.gif\" alt=\"Fruit Drop: fruit falls into a glowing well at a fruit-stand arcade, a chain of matches pops and the words Sweet! Chain x2 and Row clear! flash while Chike cheers\"></p><ul><li>DropBlox is now Fruit Drop, a brand-new game that mixes falling pieces with match-three.</li><li>Line up 3 or more of the same fruit to pop them. A full row clears too, and falling fruit can set off chains.</li><li>Make striped, wrapped and golden-star fruit for big pops.</li><li>12 levels with up to three stars each, plus an Endless mode. On a phone, use the big buttons or swipe.</li></ul><p><a href=\"#/play/game-drop-blox\">Play Fruit Drop</a></p><h2>Memory Match</h2><p><img src=\"assets/newsletter/arcade-update/memory-match.gif\" alt=\"Memory Match: yellow cards flip over to show drawn pictures, and matching pairs like two books and two crayons get a green tick\"></p><ul><li>New hand-drawn cards: books, crayons, puzzles, rockets, palettes and more.</li><li>Find all ten pairs. A matching pair stays face up with a green tick.</li><li>Your best time is saved, so you can try to beat it.</li></ul><p><a href=\"#/play/game-memory\">Play Memory Match</a></p><h2>Also new</h2><ul><li><strong>Pathbuilder:</strong> with 2 players you now both build at the same time, and the first car home wins.</li><li><strong>Chike's Gravity 4</strong>, our subscribers-only game: Easy Chike is now easier to beat, and the game has sound.</li><li><strong>The Play page:</strong> smaller game cards, so you can see more games at once.</li></ul><p>Which game will you try first?</p>", "textFirst": "after", "email": {"on": true, "subject": "8 games just got an arcade makeover", "preview": "Fruit Drop, a Maze Quest race, 3D Air Hockey and more. Come see what's new.", "message": "Big news from our Play page: eight games just got a brand-new arcade look.\n\nAir Hockey is now a 3D table against Chike. Cosmic Blast! flies you past all eight planets. Maze Quest lets you race a friend online with a room code. And DropBlox became Fruit Drop: match three fruit and set off juicy chains.\n\nSpelling Detective and Balloon Pop Math now have grades from Kindergarten to 5th, with Chike there to help, and Bounce & Bank and Memory Match have a fresh new look.\n\nWe put a short moving preview of every game in the Subscriber's Portal, with what changed in each one.", "button": "See the new games"}, "adminNote": "Draft written by Claude on 2026-10-30. NOT sent. Publishing this entry opens its email as a draft for you to review; nothing is emailed until you press Send yourself.", "gameId": "", "gamePath": "", "gameMode": "launch", "gameLabel": "", "howToPlay": [], "privateGameId": "", "privateGameKb": 0, "bookId": "", "bookMode": "launch", "bookPath": "", "videoUrl": "", "gallery": [], "buttonLabel": "", "buttonUrl": "", "vocabWord": "", "vocabSay": "", "vocabMeaning": "", "vocabExample": "", "aiPrompt": "", "aiPromptTitle": "", "aiPromptTip": "", "createdAt": "2026-10-30T12:00:00.000Z", "updatedAt": "2026-10-30T12:00:00.000Z"}$j$::jsonb)
on conflict (id) do update set data = excluded.data, updated_at = now();
